import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from 'recharts';
import { BILLING_DATA, COLORS } from '../constants';
import { DollarSign, FileText, AlertTriangle } from 'lucide-react';
import { StatCard } from './StatCard';

export const Billing: React.FC = () => {
  const totalRevenue = BILLING_DATA.reduce((acc, curr) => acc + curr.amount, 0);
  const rejected = BILLING_DATA.find(d => d.category === 'Rejected');

  const dataForChart = BILLING_DATA.map(item => ({
    name: item.category,
    value: item.amount
  }));

  const CHART_COLORS = [COLORS.mintAccent, COLORS.softBlue, COLORS.warning, COLORS.danger];

  return (
    <div className="space-y-6">
       <div className="mb-8">
          <h2 className="text-2xl font-bold text-slate-800 dark:text-slate-100">Billing & Revenue Cycle</h2>
          <p className="text-slate-500 dark:text-slate-400">Track payments, insurance claims, and rejections.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard 
            title="Total Revenue Cycle" 
            value={`$${(totalRevenue / 1000).toFixed(1)}k`} 
            trend="up" 
            change={4.5}
            icon={DollarSign}
          />
          <StatCard 
            title="Claims Rejected" 
            value={rejected?.count || 0} 
            trend="down" 
            change={1.2}
            icon={AlertTriangle}
          />
           <StatCard 
            title="Claims Processed" 
            value="655" 
            trend="up" 
            change={12}
            icon={FileText}
          />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mt-6">
           {/* Funnel / Distribution */}
           <div className="bg-white dark:bg-darkCard p-8 rounded-2xl shadow-card dark:shadow-dark-card border border-transparent dark:border-darkBorder flex flex-col items-center justify-center">
              <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 w-full text-left mb-4">Revenue Distribution</h3>
              <div className="h-[350px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={dataForChart}
                      innerRadius={80}
                      outerRadius={120}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {dataForChart.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={CHART_COLORS[index % CHART_COLORS.length]} strokeWidth={0} />
                      ))}
                    </Pie>
                    <Tooltip 
                      formatter={(value: number) => `$${value.toLocaleString()}`}
                      contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                    />
                    <Legend verticalAlign="bottom" height={36} iconType="circle" />
                  </PieChart>
                </ResponsiveContainer>
              </div>
           </div>

           {/* Detailed List */}
           <div className="bg-white dark:bg-darkCard p-8 rounded-2xl shadow-card dark:shadow-dark-card border border-transparent dark:border-darkBorder">
              <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 mb-6">Claims Status</h3>
              <div className="space-y-6">
                {BILLING_DATA.map((item, idx) => (
                  <div key={idx}>
                    <div className="flex justify-between items-end mb-2">
                      <div>
                        <p className="font-medium text-slate-700 dark:text-slate-200">{item.category}</p>
                        <p className="text-xs text-slate-400">{item.count} claims</p>
                      </div>
                      <p className="font-mono font-semibold text-slate-800 dark:text-slate-100">${item.amount.toLocaleString()}</p>
                    </div>
                    <div className="w-full bg-slate-100 dark:bg-slate-700 h-2 rounded-full overflow-hidden">
                       <div 
                        className="h-full rounded-full"
                        style={{ 
                          width: `${(item.amount / totalRevenue) * 100}%`,
                          backgroundColor: CHART_COLORS[idx]
                        }}
                       />
                    </div>
                  </div>
                ))}
              </div>

              <div className="mt-8 p-4 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-slate-100 dark:border-slate-700 text-center">
                <p className="text-sm text-slate-500 dark:text-slate-400 mb-2">Revenue Forecast for Next Week</p>
                <p className="text-2xl font-bold text-softBlue">$142,000</p>
              </div>
           </div>
        </div>
    </div>
  );
};

import React from 'react';

export interface StatMetric {
  label: string;
  value: string | number;
  change?: number; // Percentage change
  trend: 'up' | 'down' | 'neutral';
  icon?: React.ReactNode;
}

export interface AppointmentData {
  time: string;
  patients: number;
  avgWaitTime: number; // in minutes
}

export interface DiagnosticTest {
  id: string;
  type: string;
  volume: number;
  avgTurnaroundTime: number; // in hours
  status: 'Normal' | 'Critical' | 'Delayed';
}

export interface BillingStat {
  category: string;
  amount: number;
  count: number;
}

export interface StaffMember {
  id: string;
  name: string;
  role: string;
  department: string;
  status: 'Available' | 'Busy' | 'Off-Duty';
  currentLoad: number; // 0-100%
}

export enum InsightType {
  PREDICTION = 'PREDICTION',
  WARNING = 'WARNING',
  OPTIMIZATION = 'OPTIMIZATION'
}

export interface AIInsight {
  id: string;
  type: InsightType;
  title: string;
  description: string;
  confidence?: number;
}

export interface AppNotification {
  id: string;
  title: string;
  message: string;
  time: string;
  type: 'info' | 'alert' | 'success';
}

