import React, { useState, useEffect } from 'react';
import { Users, Clock, Calendar, Activity, ChevronRight } from 'lucide-react';
import { StatCard } from './StatCard';
import { PatientFlowGraph } from './PatientFlowGraph';
import { StaffList } from './StaffList';
import { APPOINTMENT_DATA, STAFF_DATA } from '../constants';
import { AppointmentData } from '../types';

export const Dashboard: React.FC = () => {
  const [timeRange, setTimeRange] = useState('Today');
  const [chartData, setChartData] = useState<AppointmentData[]>(APPOINTMENT_DATA);
  const [showAllStaff, setShowAllStaff] = useState(false);

  // Effect to simulate data fetching when time range changes
  useEffect(() => {
    // Simulate different data for different ranges
    const baseData = [...APPOINTMENT_DATA];
    const multiplier = timeRange === 'Yesterday' ? 0.8 : timeRange === 'Last Week' ? 1.2 : 1;

    const newData = baseData.map(item => ({
      ...item,
      patients: Math.round(item.patients * (multiplier + (Math.random() * 0.4 - 0.2))), // +/- 20% jitter
      avgWaitTime: Math.round(item.avgWaitTime * (multiplier + (Math.random() * 0.4 - 0.2)))
    }));

    setChartData(newData);
  }, [timeRange]);

  // Handle staff list display (Top 5 vs All)
  const displayedStaff = showAllStaff ? STAFF_DATA : STAFF_DATA.slice(0, 5);

  return (
    <div className="space-y-6">
      {/* Top Metrics */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-6">
        <StatCard 
          title="Total Appointments" 
          value={timeRange === 'Today' ? "128" : timeRange === 'Yesterday' ? "110" : "845"} 
          change={12} 
          trend={timeRange === 'Yesterday' ? "down" : "up"}
          icon={Calendar}
          subtext={`${timeRange}'s schedule`}
        />
        <StatCard 
          title="Avg Wait Time" 
          value={timeRange === 'Today' ? "14m" : "18m"} 
          change={5} 
          trend="down" 
          icon={Clock}
          subtext="Running efficiently"
        />
        <StatCard 
          title="Patients In-Clinic" 
          value="42" 
          change={8} 
          trend="up" 
          icon={Users}
          subtext="Current throughput"
        />
        <StatCard 
          title="Staff Utilization" 
          value="88%" 
          change={2} 
          trend="up" 
          icon={Activity}
          subtext="High load warning"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Chart */}
        <div className="lg:col-span-2 bg-white dark:bg-darkCard rounded-2xl p-6 shadow-card dark:shadow-dark-card border border-transparent dark:border-darkBorder">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-6 gap-4">
            <div>
              <h3 className="font-semibold text-slate-800 dark:text-slate-100 text-lg">Patient Flow</h3>
              <p className="text-sm text-slate-400">Appointments vs Wait Time</p>
            </div>
            <select 
              value={timeRange}
              onChange={(e) => setTimeRange(e.target.value)}
              className="bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-sm text-slate-600 dark:text-slate-200 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-softBlue transition-all cursor-pointer"
            >
              <option value="Today">Today</option>
              <option value="Yesterday">Yesterday</option>
              <option value="Last Week">Last Week</option>
            </select>
          </div>
          <div className="h-[300px] w-full">
            <PatientFlowGraph data={chartData} />
          </div>
        </div>

        {/* Staff Status */}
        <div className="bg-white dark:bg-darkCard rounded-2xl p-6 shadow-card dark:shadow-dark-card border border-transparent dark:border-darkBorder flex flex-col max-h-[420px]">
          <div className="flex items-center justify-between mb-4 shrink-0">
            <h3 className="font-semibold text-slate-800 dark:text-slate-100 text-lg">Staff Availability</h3>
            <button 
              onClick={() => setShowAllStaff(!showAllStaff)}
              className="text-softBlue text-sm font-medium hover:text-blue-600 transition-colors flex items-center"
            >
              {showAllStaff ? 'Show Less' : 'View All'}
              <ChevronRight size={14} className={`transition-transform duration-200 ${showAllStaff ? 'rotate-90' : ''}`} />
            </button>
          </div>
          <div className="flex-1 overflow-y-auto pr-1 custom-scrollbar">
            <StaffList staff={displayedStaff} />
          </div>
        </div>
      </div>

      {/* Room Status (Simplified Grid) */}
      <div className="bg-white dark:bg-darkCard rounded-2xl p-6 shadow-card dark:shadow-dark-card border border-transparent dark:border-darkBorder">
        <h3 className="font-semibold text-slate-800 dark:text-slate-100 text-lg mb-4">Room Occupancy</h3>
        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-8 gap-4">
            {[101, 102, 103, 104, 105, 106, 201, 202].map((room, i) => {
               const isOccupied = i % 3 === 0 || i === 5;
               return (
                <div key={room} className={`p-3 rounded-xl border transition-colors cursor-default hover:shadow-md ${
                  isOccupied 
                    ? 'bg-red-50 dark:bg-red-900/10 border-red-100 dark:border-red-900/30' 
                    : 'bg-green-50 dark:bg-green-900/10 border-green-100 dark:border-green-900/30'
                } flex flex-col gap-1 group`}>
                    <span className="text-xs font-bold text-slate-400 dark:text-slate-500">Room {room}</span>
                    <div className="flex items-center justify-between">
                      <span className={`text-sm font-medium ${isOccupied ? 'text-red-600 dark:text-red-400' : 'text-green-600 dark:text-green-400'}`}>
                        {isOccupied ? 'Occupied' : 'Free'}
                      </span>
                      <div className={`w-2 h-2 rounded-full ${isOccupied ? 'bg-red-500' : 'bg-green-500'}`}></div>
                    </div>
                </div>
              );
            })}
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { InsightType, AIInsight } from '../types';

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const generateOperationalInsights = async (
  contextData: string
): Promise<AIInsight[]> => {
  if (!apiKey) {
    console.warn("API Key is missing");
    return [
      {
        id: 'mock-1',
        type: InsightType.WARNING,
        title: 'API Key Missing',
        description: 'Please configure your Gemini API Key to see real-time insights.',
      }
    ];
  }

  try {
    const model = 'gemini-2.5-flash';
    const prompt = `
      You are an expert Healthcare Operations Analyst AI named MediOps IQ.
      Analyze the following operational data JSON and provide 3-4 key actionable insights.

      Context Data:
      ${contextData}

      Return the response as a pure JSON array of objects with the following structure (no markdown, no code blocks):
      [
        {
          "id": "unique_string",
          "type": "PREDICTION" | "WARNING" | "OPTIMIZATION",
          "title": "Short concise headline",
          "description": "Detailed explanation of the insight and recommended action.",
          "confidence": number (0-100)
        }
      ]
    `;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
      }
    });

    const text = response.text;
    if (!text) return [];

    return JSON.parse(text) as AIInsight[];
  } catch (error) {
    console.error("Error fetching Gemini insights:", error);
    return [
      {
        id: 'err-1',
        type: InsightType.WARNING,
        title: 'Analysis Failed',
        description: 'Unable to generate insights at this moment. Please try again later.',
      }
    ];
  }
};

import React, { useState, useEffect } from 'react';
import { Sparkles, TrendingUp, AlertTriangle, RefreshCw, Lightbulb } from 'lucide-react';
import { generateOperationalInsights } from '../services/geminiService';
import { APPOINTMENT_DATA, STAFF_DATA, DIAGNOSTIC_DATA, BILLING_DATA } from '../constants';
import { AIInsight, InsightType } from '../types';

export const AIInsights: React.FC = () => {
  const [insights, setInsights] = useState<AIInsight[]>([]);
  const [loading, setLoading] = useState(false);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);

  const fetchData = async () => {
    setLoading(true);
    // Aggregate data for context
    const context = JSON.stringify({
      appointments: APPOINTMENT_DATA,
      staff: STAFF_DATA,
      diagnostics: DIAGNOSTIC_DATA,
      billing: BILLING_DATA,
    });

    const results = await generateOperationalInsights(context);
    setInsights(results);
    setLastUpdated(new Date());
    setLoading(false);
  };

  // Initial fetch
  useEffect(() => {
    fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="space-y-8 max-w-5xl mx-auto">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between">
        <div>
           <h2 className="text-3xl font-bold text-slate-800 dark:text-slate-100 flex items-center gap-3">
             <Sparkles className="text-softBlue" />
             MediOps IQ Intelligence
           </h2>
           <p className="text-slate-500 dark:text-slate-400 mt-2">Real-time operational analysis powered by Gemini 2.5 Flash.</p>
        </div>
        <button 
          onClick={fetchData}
          disabled={loading}
          className="mt-4 md:mt-0 flex items-center gap-2 px-5 py-2.5 bg-softBlue text-white rounded-xl font-medium hover:bg-blue-500 disabled:opacity-70 transition-all shadow-soft hover:shadow-lg"
        >
          {loading ? <RefreshCw className="animate-spin" size={18} /> : <RefreshCw size={18} />}
          {loading ? 'Analyzing...' : 'Refresh Analysis'}
        </button>
      </div>

      {/* Highlight Banner */}
      <div className="bg-gradient-to-r from-softBlue to-blue-600 rounded-3xl p-8 text-white shadow-xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white opacity-10 rounded-full -mr-16 -mt-16 blur-3xl pointer-events-none"></div>
        <h3 className="text-2xl font-bold mb-2 relative z-10">Predictive Surge Detected</h3>
        <p className="text-blue-100 max-w-xl relative z-10 leading-relaxed">
          Based on historical patterns and current appointment velocity, expect a <strong>15% patient surge</strong> tomorrow between 09:00 and 11:00. Recommend scheduling 2 additional RNs for Triage.
        </p>
      </div>

      {/* Insights Grid */}
      <div className="grid gap-6">
        {loading ? (
          // Skeleton Loaders
          [1, 2, 3].map(i => (
            <div key={i} className="h-32 bg-white dark:bg-darkCard rounded-2xl animate-pulse shadow-card dark:shadow-dark-card border border-transparent dark:border-darkBorder" />
          ))
        ) : (
          insights.map((insight) => (
            <div 
              key={insight.id} 
              className={`p-6 rounded-2xl border shadow-card dark:shadow-dark-card transition-all hover:-translate-y-1 ${
                insight.type === InsightType.WARNING 
                  ? 'border-orange-200 dark:border-orange-900/50 bg-orange-50/50 dark:bg-orange-900/10' 
                  : insight.type === InsightType.OPTIMIZATION 
                  ? 'border-green-200 dark:border-green-900/50 bg-green-50/50 dark:bg-green-900/10' 
                  : 'border-blue-100 dark:border-blue-900/30 bg-white dark:bg-darkCard'
              }`}
            >
              <div className="flex items-start gap-4">
                <div className={`p-3 rounded-xl shrink-0 ${
                  insight.type === InsightType.WARNING ? 'bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400' :
                  insight.type === InsightType.OPTIMIZATION ? 'bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400' :
                  'bg-blue-100 dark:bg-blue-900/30 text-softBlue'
                }`}>
                  {insight.type === InsightType.WARNING ? <AlertTriangle size={24} /> :
                   insight.type === InsightType.OPTIMIZATION ? <TrendingUp size={24} /> :
                   <Lightbulb size={24} />}
                </div>
                <div>
                  <div className="flex items-center gap-3 mb-1">
                    <h4 className="text-lg font-bold text-slate-800 dark:text-slate-100">{insight.title}</h4>
                    <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded-md ${
                       insight.type === InsightType.WARNING ? 'bg-white dark:bg-darkBg text-orange-600 dark:text-orange-400' :
                       insight.type === InsightType.OPTIMIZATION ? 'bg-white dark:bg-darkBg text-green-600 dark:text-green-400' :
                       'bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400'
                    }`}>
                      {insight.type}
                    </span>
                  </div>
                  <p className="text-slate-600 dark:text-slate-300 leading-relaxed">{insight.description}</p>
                  {insight.confidence && (
                    <div className="mt-3 flex items-center gap-2">
                      <div className="h-1.5 w-24 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                        <div className="h-full bg-slate-400 dark:bg-slate-500" style={{ width: `${insight.confidence}%` }} />
                      </div>
                      <span className="text-xs font-mono text-slate-400 dark:text-slate-500">{insight.confidence}% Confidence</span>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {lastUpdated && (
