import React, { useState, useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { DIAGNOSTIC_DATA, COLORS } from '../constants';
import { AlertCircle, CheckCircle, Clock, Filter } from 'lucide-react';

export const Diagnostics: React.FC = () => {
  const [filterStatus, setFilterStatus] = useState<'All' | 'Critical' | 'Delayed' | 'Normal'>('All');

  const filteredData = useMemo(() => {
    if (filterStatus === 'All') return DIAGNOSTIC_DATA;
    return DIAGNOSTIC_DATA.filter(item => item.status === filterStatus);
  }, [filterStatus]);

  const counts = {
    Critical: DIAGNOSTIC_DATA.filter(d => d.status === 'Critical').length,
    Delayed: DIAGNOSTIC_DATA.filter(d => d.status === 'Delayed').length,
    Normal: DIAGNOSTIC_DATA.filter(d => d.status === 'Normal').length,
  };

  return (
    <div className="space-y-6">
       <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 dark:text-slate-100">Diagnostic Workflows</h2>
          <p className="text-slate-500 dark:text-slate-400">Monitor test turnaround times and bottlenecks.</p>
        </div>

        {/* Interactive Filters */}
        <div className="flex flex-wrap gap-2">
           <button 
             onClick={() => setFilterStatus('Critical')}
             className={`px-3 py-1.5 rounded-full text-sm font-medium flex items-center gap-2 transition-all border ${
               filterStatus === 'Critical' 
                ? 'bg-red-100 dark:bg-red-900/30 border-red-200 dark:border-red-800 text-red-700 dark:text-red-400 shadow-sm' 
                : 'bg-red-50 dark:bg-red-900/10 border-transparent text-red-600 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-900/20'
             }`}
           >
             <AlertCircle size={14} />
             Critical: {counts.Critical}
           </button>

           <button 
             onClick={() => setFilterStatus('Delayed')}
             className={`px-3 py-1.5 rounded-full text-sm font-medium flex items-center gap-2 transition-all border ${
               filterStatus === 'Delayed' 
                ? 'bg-orange-100 dark:bg-orange-900/30 border-orange-200 dark:border-orange-800 text-orange-700 dark:text-orange-400 shadow-sm' 
                : 'bg-orange-50 dark:bg-orange-900/10 border-transparent text-orange-600 dark:text-orange-400 hover:bg-orange-100 dark:hover:bg-orange-900/20'
             }`}
           >
             <Clock size={14} />
             Delayed: {counts.Delayed}
           </button>

           <button 
             onClick={() => setFilterStatus('Normal')}
             className={`px-3 py-1.5 rounded-full text-sm font-medium flex items-center gap-2 transition-all border ${
               filterStatus === 'Normal' 
                ? 'bg-green-100 dark:bg-green-900/30 border-green-200 dark:border-green-800 text-green-700 dark:text-green-400 shadow-sm' 
                : 'bg-green-50 dark:bg-green-900/10 border-transparent text-green-600 dark:text-green-400 hover:bg-green-100 dark:hover:bg-green-900/20'
             }`}
           >
             <CheckCircle size={14} />
             On Track: {counts.Normal}
           </button>

           {filterStatus !== 'All' && (
             <button 
                onClick={() => setFilterStatus('All')}
                className="px-3 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 text-sm font-medium hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors flex items-center gap-1"
             >
               <Filter size={12} />
               Reset View
             </button>
           )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Turnaround Time Chart */}
        <div className="bg-white dark:bg-darkCard p-6 rounded-2xl shadow-card dark:shadow-dark-card border border-transparent dark:border-darkBorder">
          <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 mb-6">Avg Turnaround Time (Hours)</h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={filteredData} layout="vertical" margin={{ left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#E2E8F0" />
                <XAxis type="number" hide />
                <YAxis 
                  dataKey="type" 
                  type="category" 
                  axisLine={false} 
                  tickLine={false}
                  width={100}
                  tick={{ fill: '#5B6570', fontSize: 12, fontWeight: 500 }}
                />
                <Tooltip 
                  cursor={{ fill: '#F1F5F9' }}
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                />
                <Bar dataKey="avgTurnaroundTime" radius={[0, 4, 4, 0]} barSize={20}>
                  {filteredData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.avgTurnaroundTime > 20 ? COLORS.danger : COLORS.softBlue} />
                  ))}
