        {/* Volume Status */}
        <div className="bg-white dark:bg-darkCard p-6 rounded-2xl shadow-card dark:shadow-dark-card border border-transparent dark:border-darkBorder flex flex-col h-full">
          <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 mb-4">
            Test Queue Status <span className="text-slate-400 font-normal text-sm ml-2">({filteredData.length})</span>
          </h3>
          <div className="space-y-4 overflow-y-auto flex-1 max-h-[400px] custom-scrollbar pr-2">
            {filteredData.length > 0 ? filteredData.map((test) => (
              <div key={test.id} className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-slate-100 dark:border-slate-700 hover:border-slate-200 dark:hover:border-slate-600 transition-colors">
                <div className="flex items-center gap-4">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 ${
                    test.status === 'Critical' ? 'bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400' :
                    test.status === 'Delayed' ? 'bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400' :
                    'bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400'
                  }`}>
                     {test.status === 'Critical' ? <AlertCircle size={20}/> : test.status === 'Delayed' ? <Clock size={20}/> : <CheckCircle size={20}/>}
                  </div>
                  <div>
                     <h4 className="font-semibold text-slate-700 dark:text-slate-200">{test.type}</h4>
                     <p className="text-xs text-slate-500 dark:text-slate-400">{test.volume} pending</p>
                  </div>
                </div>
                <div className="text-right shrink-0">
                  <span className={`inline-block px-2 py-1 rounded-md text-xs font-bold ${
                    test.status === 'Critical' ? 'bg-red-200 dark:bg-red-900/50 text-red-800 dark:text-red-300' :
                    test.status === 'Delayed' ? 'bg-orange-200 dark:bg-orange-900/50 text-orange-800 dark:text-orange-300' :
                    'bg-green-200 dark:bg-green-900/50 text-green-800 dark:text-green-300'
                  }`}>
                    {test.status.toUpperCase()}
                  </span>
                  <p className="text-xs font-mono text-slate-400 mt-1">{test.avgTurnaroundTime}h avg</p>
                </div>
              </div>
            )) : (
               <div className="text-center py-12 text-slate-400">
                 <Filter className="mx-auto mb-2 opacity-50" size={32} />
                 <p>No {filterStatus.toLowerCase()} tests found.</p>
               </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};
